"use client";

import React, { useState, useMemo } from "react";
import { 
  Calendar as CalendarIcon, 
  Users, 
  CheckCircle2, 
  AlertTriangle, 
  Plane, 
  Stethoscope, 
  Briefcase, 
  Baby, 
  Umbrella, 
  GraduationCap, 
  HeartPulse, 
  AlertOctagon,
  ChevronRight,
  Info
} from "lucide-react";

// --- CONFIGURATION ---
const HOLIDAYS = ["2026-01-26"]; // Republic Day
const TEAM_OUT = [
  { name: "Sarah J.", role: "Manager", date: "2026-01-20", avatar: "SJ" },
  { name: "Mike R.", role: "Backend", date: "2026-01-22", avatar: "MR" }
];

// Handles "Many Types" of leaves gracefully
const LEAVE_TYPES = [
  { id: "annual", label: "Annual Leave", icon: Plane, balance: 18, color: "text-blue-600", bg: "bg-blue-50" },
  { id: "sick", label: "Sick Leave", icon: Stethoscope, balance: 12, color: "text-rose-600", bg: "bg-rose-50" },
  { id: "casual", label: "Casual Leave", icon: Umbrella, balance: 6, color: "text-amber-600", bg: "bg-amber-50" },
  { id: "parental", label: "Parental Leave", icon: Baby, balance: 90, color: "text-purple-600", bg: "bg-purple-50" },
  { id: "study", label: "Study Leave", icon: GraduationCap, balance: 5, color: "text-indigo-600", bg: "bg-indigo-50" },
  { id: "bereavement", label: "Bereavement", icon: HeartPulse, balance: 10, color: "text-slate-600", bg: "bg-slate-100" },
  { id: "unpaid", label: "Loss of Pay", icon: AlertOctagon, balance: 0, color: "text-red-600", bg: "bg-red-50" },
];

export default function CompactAbsencePortal() {
  const [range, setRange] = useState<{ start: string; end: string }>({ start: "", end: "" });
  const [typeId, setTypeId] = useState("annual");
  const [reason, setReason] = useState("");

  // --- LOGIC ENGINE ---
  const stats = useMemo(() => {
    if (!range.start || !range.end) return { total: 0, working: 0, weekends: 0, holidays: 0, conflict: false };
    
    let total = 0, working = 0, weekends = 0, holidays = 0, conflict = false;
    let cur = new Date(range.start);
    let end = new Date(range.end);

    while (cur <= end) {
      const dateStr = cur.toISOString().split('T')[0];
      const day = cur.getDay();
      
      total++;
      if (HOLIDAYS.includes(dateStr)) holidays++;
      else if (day === 0 || day === 6) weekends++;
      else {
        working++;
        if (TEAM_OUT.some(t => t.date === dateStr)) conflict = true;
      }
      cur.setDate(cur.getDate() + 1);
    }
    return { total, working, weekends, holidays, conflict };
  }, [range]);

  const handleDateClick = (dateStr: string) => {
    if (!range.start || (range.start && range.end)) {
      setRange({ start: dateStr, end: "" });
    } else {
      const s = new Date(range.start);
      const e = new Date(dateStr);
      if (e < s) setRange({ start: dateStr, end: "" });
      else setRange({ ...range, end: dateStr });
    }
  };

  const selectedType = LEAVE_TYPES.find(t => t.id === typeId)!;

  return (
    <div className="h-screen overflow-hidden bg-[#F8FAFC] font-sans text-slate-800 flex flex-col">
      
      {/* 1. COMPACT HEADER */}
      <header className="px-6 py-4 bg-white border-b border-slate-200 flex-none flex items-center justify-between z-10">
        <div>
          <h1 className="text-xl font-bold text-slate-900 flex items-center gap-2">
            <CalendarIcon className="h-5 w-5 text-blue-600" /> Request Absence
          </h1>
        </div>
        <div className="flex items-center gap-3">
           <div className="text-xs text-right">
              <p className="font-bold text-slate-900">Sarah Jenkins</p>
              <p className="text-slate-400">Approving Manager</p>
           </div>
           <div className="h-8 w-8 rounded-full bg-slate-200 flex items-center justify-center text-xs font-bold">SJ</div>
        </div>
      </header>

      {/* 2. MAIN WORKSPACE (3 Columns) */}
      <div className="flex-1 grid grid-cols-12 gap-0 overflow-hidden">
        
        {/* COL 1: LEAVE TYPES (Scrollable List) - 20% Width */}
        <aside className="col-span-3 lg:col-span-2 border-r border-slate-200 bg-white flex flex-col overflow-hidden">
          <div className="p-4 border-b border-slate-100 bg-slate-50/50">
            <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Select Category</p>
          </div>
          <div className="flex-1 overflow-y-auto p-2 space-y-1">
            {LEAVE_TYPES.map((t) => (
              <button
                key={t.id}
                onClick={() => setTypeId(t.id)}
                className={`w-full flex items-center gap-3 p-3 rounded-lg text-left transition-all ${
                  typeId === t.id 
                  ? "bg-blue-50 ring-1 ring-blue-500/20" 
                  : "hover:bg-slate-50"
                }`}
              >
                <div className={`p-2 rounded-md ${t.bg} ${t.color} shrink-0`}>
                  <t.icon className="h-4 w-4" />
                </div>
                <div>
                  <p className={`text-xs font-bold ${typeId === t.id ? "text-slate-900" : "text-slate-600"}`}>{t.label}</p>
                  <p className="text-[10px] text-slate-400">{t.balance} Days Avail</p>
                </div>
                {typeId === t.id && <ChevronRight className="h-4 w-4 text-blue-500 ml-auto" />}
              </button>
            ))}
          </div>
          <div className="p-4 border-t border-slate-100">
             <div className="flex items-center gap-2 text-[10px] text-slate-400">
                <Info className="h-3 w-3" />
                <span>Policies updated Jan 2026</span>
             </div>
          </div>
        </aside>

        {/* COL 2: CALENDAR (The Stage) - 50% Width */}
        <main className="col-span-5 lg:col-span-6 bg-slate-50/50 p-6 flex flex-col overflow-y-auto">
          <div className="mb-6 flex items-center justify-between">
            <h2 className="text-xl font-bold text-slate-800">January 2026</h2>
            <div className="flex gap-4 text-[10px] font-bold uppercase tracking-widest text-slate-400">
              <span className="flex items-center gap-1"><span className="h-2 w-2 rounded-full bg-blue-600"/>Selected</span>
              <span className="flex items-center gap-1"><span className="h-2 w-2 rounded-full bg-orange-400"/>Holiday</span>
              <span className="flex items-center gap-1"><span className="h-2 w-2 rounded-full bg-slate-200"/>Weekend</span>
            </div>
          </div>

          <div className="bg-white rounded-2xl border border-slate-200 shadow-sm p-6 flex-1 min-h-[400px]">
            <div className="grid grid-cols-7 gap-2 h-full content-start">
              {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(d => (
                <div key={d} className="text-center text-[10px] font-black text-slate-300 uppercase mb-2">{d}</div>
              ))}
              
              {/* Jan 1 is Thursday */}
              {[null, null, null].map((_, i) => <div key={`e-${i}`} />)}

              {Array.from({ length: 31 }).map((_, i) => {
                const day = i + 1;
                const dateStr = `2026-01-${day < 10 ? `0${day}` : day}`;
                const isHoliday = HOLIDAYS.includes(dateStr);
                const dateObj = new Date(2026, 0, day);
                const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6;
                const isSelected = range.start === dateStr || range.end === dateStr;
                const inRange = range.start && range.end && dateStr > range.start && dateStr < range.end;

                return (
                  <button
                    key={day}
                    onClick={() => handleDateClick(dateStr)}
                    className={`
                      relative h-16 rounded-lg text-sm font-bold transition-all border
                      ${isSelected ? "bg-blue-600 text-white border-blue-600 shadow-md z-10 scale-105" : ""}
                      ${inRange ? "bg-blue-50 text-blue-600 border-blue-50" : ""}
                      ${isHoliday && !inRange && !isSelected ? "bg-orange-50 border-orange-100 text-orange-600" : ""}
                      ${isWeekend && !isSelected && !inRange ? "bg-slate-50 border-transparent text-slate-300" : "bg-white border-slate-100 hover:border-blue-300 hover:shadow-sm"}
                    `}
                  >
                    {day}
                    {isHoliday && !inRange && <span className="absolute bottom-1 right-1 h-1.5 w-1.5 rounded-full bg-orange-400" />}
                  </button>
                );
              })}
            </div>
          </div>
        </main>

        {/* COL 3: IMPACT & ACTION (Context) - 30% Width */}
        <aside className="col-span-4 lg:col-span-4 bg-white border-l border-slate-200 flex flex-col overflow-y-auto">
          
          {/* Section A: Balance Impact */}
          <div className="p-6 border-b border-slate-100">
             <div className="flex items-center gap-2 mb-4">
                <selectedType.icon className={`h-4 w-4 ${selectedType.color}`} />
                <span className="text-sm font-bold uppercase tracking-wide text-slate-500">{selectedType.label}</span>
             </div>
             
             <div className="flex items-end gap-2 mb-3">
                <span className="text-4xl font-black text-slate-900">{selectedType.balance - stats.working}</span>
                <span className="text-xs font-bold text-slate-400 mb-1.5">Days Left</span>
             </div>

             {/* Progress Bar */}
             <div className="h-2 w-full bg-slate-100 rounded-full overflow-hidden flex">
                <div className={`h-full ${selectedType.color.replace('text-', 'bg-')} opacity-20`} style={{ width: `${((selectedType.balance - stats.working)/selectedType.balance)*100}%` }} />
                <div className="h-full bg-rose-500 transition-all duration-500" style={{ width: `${(stats.working/selectedType.balance)*100}%` }} />
             </div>
             {stats.working > 0 && (
                <p className="mt-2 text-[10px] text-right text-rose-500 font-bold">- {stats.working} Days deduction</p>
             )}
          </div>

          {/* Section B: Team Context */}
          <div className="p-6 border-b border-slate-100 flex-1">
             <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400 mb-4">Team Availability</p>
             
             {stats.conflict && (
                <div className="mb-4 rounded-lg bg-amber-50 p-3 border border-amber-100 flex gap-2">
                   <AlertTriangle className="h-4 w-4 text-amber-600 shrink-0" />
                   <p className="text-xs font-bold text-amber-800">Conflict Warning: Key members are out.</p>
                </div>
             )}

             <div className="space-y-3">
                {TEAM_OUT.map((m, i) => (
                   <div key={i} className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                         <div className="h-6 w-6 rounded-full bg-slate-100 flex items-center justify-center text-[9px] font-bold text-slate-600 border">
                            {m.avatar}
                         </div>
                         <span className="text-xs font-bold text-slate-700">{m.name}</span>
                      </div>
                      <span className="text-[10px] font-bold bg-slate-50 px-2 py-1 rounded text-slate-500">
                         Out Jan {m.date.split('-')[2]}
                      </span>
                   </div>
                ))}
             </div>
          </div>

          {/* Section C: Action Area (Sticky Bottom) */}
          <div className="p-6 bg-slate-50">
             <label className="text-[10px] font-bold uppercase text-slate-400 mb-2 block">Reason</label>
             <textarea 
               value={reason}
               onChange={(e) => setReason(e.target.value)}
               className="w-full h-20 rounded-xl border border-slate-200 p-3 text-xs font-medium focus:ring-2 focus:ring-blue-500 outline-none resize-none bg-white mb-4"
               placeholder="Why are you taking leave?"
             />
             
             <div className="flex justify-between items-center mb-4 text-xs font-bold text-slate-500">
                <span>Selected: {stats.total} Days</span>
                <span>Weekends: {stats.weekends}</span>
             </div>

             <button 
               disabled={!range.end}
               className="w-full rounded-xl bg-slate-900 py-3 text-sm font-bold text-white shadow-lg transition-all hover:bg-black disabled:bg-slate-300 disabled:shadow-none"
             >
               {range.end ? `Submit Request (${stats.working} days)` : "Select Dates"}
             </button>
          </div>

        </aside>

      </div>
    </div>
  );
}